window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-12691\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπολιορκέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1452 na letra ε · nº geral 12691</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 forçar a render-se, a capitular ♦ pas. 2 ser forçado a capitular.</p></section></article>\n<article id=\"entry-dgp-12692\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπομπεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1453 na letra ε · nº geral 12692</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conduzir em procissão 2 caminhar com ar solene 3 expor ao riso público.</p></section></article>\n<article id=\"entry-dgp-12693\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπομπή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1454 na letra ε · nº geral 12693</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 envio (de colonos) 2 expedição 3 repúdio (de mulher); divórcio. 〈ἐκπέμπω〉</p></section></article>\n<article id=\"entry-dgp-12694\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1455 na letra ε · nº geral 12694</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 executar: ἐκπ. τἀντελαμένα eur. executar as ordens, πότεροι δὲ ἃ ἂν μάθωσιν ἱκανότερα τῷ σώματι ἐκπονεῖν xen. quais deles são mais capazes de pôr em prática o que venham a aprender 2 ornar: πέπλοισιν ἐκπ. eur. ornar com peplos 3 elaborar; moldar: αἱ δὲ ταύτην [τὴν ὕλην] ἐκπονοῦσαι καὶ κατεργαζόμεναι τέχναι plut. as artes que elaboraram e trabalharam este material, ἐκπ. ὕλην moldar uma matéria 4 educar; formar: Χείρων ἐξέπονησεν eur. Quirão educou-o 5 consumir; digerir (alimento) 6 intr. processar alimentos (no estômago); fazer a digestão 7 exercitar-se em algo, ac.: ἐκπ. τὰ πρὸς πόλεμον xen. exercitar-se nas manobras militares, ὀρχήσεις ἐκπονοῦντες pol. exercitando-se na dança 8 conseguir com esforço; esforçar-se por algo, ac. ou or. conj. (ὅπως) ou inf.: ἐκπ. βίον eur. conseguir com esforço os meios de vida, τοὺς θεοὺς ἐκπ. φράζειν eur. conseguir com esforço que os deuses falem, σοὶ ἐκπονῶν ὅπως σύ eur. esforçando-se para que tu 9 conseguir afastar ou desviar algo, ac., de alguém, gen.: τῶν δ᾽ ἐμῶν τέκνων οὐκ ἐκπονήσω θάνατον; eur. não conseguirei afastar a morte de meus filhos? ♦ méd. 10 exercitar-se em, ac. 11 realizar.</p></section></article>\n<article id=\"entry-dgp-12695\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπορεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1456 na letra ε · nº geral 12695</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer sair de; levar alguém, ac., de um lugar, gen. ♦ pas. 2 afastar-se de; sair de, ἐκ e gen. 3 crist. proceder de.</p></section></article>\n<article id=\"entry-dgp-12696\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπορθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1457 na letra ε · nº geral 12696</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 arruinar; devastar 2 saquear; pilhar ♦ pas. 3 (pessoa) ser consumido.</p></section></article>\n<article id=\"entry-dgp-12697\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπορίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1458 na letra ε · nº geral 12697</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fornecer; propiciar algo, ac., a alguém, dat. 2 imaginar; inventar; maquinar ♦ méd. 3 propiciar para si; obter.</p></section></article>\n<article id=\"entry-dgp-12698\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπορνεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1459 na letra ε · nº geral 12698</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crist. 1 prostituir-se 2 tornar-se viciado 3 prostituir 4 fazer prostituir-se.</p></section></article>\n<article id=\"entry-dgp-12699\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκποτάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1460 na letra ε · nº geral 12699</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 (flocos de neve) cair esvoaçando 2 voar.</p></section></article>\n<article id=\"entry-dgp-12700\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκποτέονται</h1><div class=\"entry-meta\"><span>DGP · ordem 1461 na letra ε · nº geral 12700</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. pres. jôn. de ἐκποτάομαι.</p></section></article>\n<article id=\"entry-dgp-12701\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπράσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1462 na letra ε · nº geral 12701</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω 1 executar; cumprir; acabar algo, ac.; ἐκπ. ὡς fazer de modo que 2 fazer tornar-se; mudar em, εἰς e ac. 3 acabar; eliminar; matar 4 fazer pagar algo, ac., a alguém, ac.; cobrar; extorquir ♦ méd. 5 fazer pagar; vingar-se de algo, ac., contra alguém, πρός e ac. 6 consumar uma vingança ♦ pas., rar. 7 ser reclamado em pagamento.</p></section></article>\n<article id=\"entry-dgp-12702\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπραΰνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1463 na letra ε · nº geral 12702</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adoçar; acalmar.</p></section></article>\n<article id=\"entry-dgp-12703\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπρεπής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1464 na letra ε · nº geral 12703</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 superior; distinto; notável 2 inconveniente; indecoroso. 〈ἐκ, πρέπω〉</p></section></article>\n<article id=\"entry-dgp-12704\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπρεπῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1465 na letra ε · nº geral 12704</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de modo notável; de maneira superior 2 inconvenientemente; de modo indecoroso.</p></section></article>\n<article id=\"entry-dgp-12705\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπρησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1466 na letra ε · nº geral 12705</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">abrasamento. 〈ἐκπίμπρημι〉</p></section></article>\n<article id=\"entry-dgp-12706\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπρήσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1467 na letra ε · nº geral 12706</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐκπράσσω.</p></section></article>\n<article id=\"entry-dgp-12707\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπρίασθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1468 na letra ε · nº geral 12707</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 (aor.2 ind. ἐξεπριάμην) 1 comprar novamente algo, ac., de alguém, παρά e gen. 2 comprar; corromper alguém: ἐκπ. τοὺς κατηγόρους lís. comprar os acusadores, μέρει τῶν ἀδικημάτων τὸν κίνδυνον ἐξεπρίαντο lís. compraram o risco do processo com uma parte das injustiças. 〈ἐκ, πρίασθαι〉</p></section></article>\n<article id=\"entry-dgp-12708\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπρίω</h1><div class=\"entry-meta\"><span>DGP · ordem 1469 na letra ε · nº geral 12708</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">serrar.</p></section></article>\n<article id=\"entry-dgp-12709\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπρόθεσμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1470 na letra ε · nº geral 12709</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que está atrasado 2 vindo muito tarde; tardio 3 que passou da idade de, gen.</p></section></article>\n<article id=\"entry-dgp-12710\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπροκαλέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1471 na letra ε · nº geral 12710</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 chamar para fora de, gen. ou ἐκ e gen. 2 invocar.</p></section></article>\n<article id=\"entry-dgp-12711\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπρολείπω</h1><div class=\"entry-meta\"><span>DGP · ordem 1472 na letra ε · nº geral 12711</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 abandonar; deixar 2 poupar.</p></section></article>\n<article id=\"entry-dgp-12712\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπροτιμάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1473 na letra ε · nº geral 12712</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">honrar acima de tudo; colocar acima de tudo.</p></section></article>\n<article id=\"entry-dgp-12713\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπτερύσσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1474 na letra ε · nº geral 12713</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estender suas asas.</p></section></article>\n<article id=\"entry-dgp-12714\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπτήσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1475 na letra ε · nº geral 12714</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. dór. 2ª sing. ἐξέπταξας) fazer sair tremendo todo; assustar.</p></section></article>\n<article id=\"entry-dgp-12715\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπτύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1476 na letra ε · nº geral 12715</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐξέπτυσα) 1 rejeitar cuspindo; cuspir 2 rejeitar com desprezo; desdenhar; desprezar 3 rejeitar; abortar ♦ méd. 4 cuspir.</p></section></article>\n<article id=\"entry-dgp-12716\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπυνθάνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1477 na letra ε · nº geral 12716</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκπεύσομαι etc.) 1 procurar informar-se; procurar saber algo, ac., junto de alguém, gen. 2 aprender; ficar sabendo 3 aprender de alguém, gen.; perguntar a alguém 4 saber que, part.</p></section></article>\n<article id=\"entry-dgp-12717\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπυρόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1478 na letra ε · nº geral 12717</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 queimar inteiramente; consumir 2 incendiar; inflamar 3 colocar no fogo; aquecer ♦ pas. 4 pegar fogo; incendiar-se; inflamar-se 5 consumir-se.</p></section></article>\n<article id=\"entry-dgp-12718\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπύρωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1479 na letra ε · nº geral 12718</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o pegar fogo; combustão; incêndio; abrasamento; conflagração 2 erupção (vulcão) 3 calor excessivo; inflamação 4 Medic. pirexia; febre. 〈ἐκπυρόω〉</p></section></article>\n<article id=\"entry-dgp-12719\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπυστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1480 na letra ε · nº geral 12719</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comunicado; conhecido. 〈ἐκπυνθά­νομαι〉</p></section></article>\n<article id=\"entry-dgp-12720\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1481 na letra ε · nº geral 12720</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">copo; taça. 〈ἐκπίνω〉</p></section></article>\n<article id=\"entry-dgp-12721\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπωτάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1482 na letra ε · nº geral 12721</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐξεπωτήθην) = ἐκποτάομαι.</p></section></article>\n<article id=\"entry-dgp-12722\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκραγήσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1483 na letra ε · nº geral 12722</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐκρήγνυμι.</p></section></article>\n<article id=\"entry-dgp-12723\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκραγον</h1><div class=\"entry-meta\"><span>DGP · ordem 1484 na letra ε · nº geral 12723</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κράζω.</p></section></article>\n<article id=\"entry-dgp-12724\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκράθην</h1><div class=\"entry-meta\"><span>DGP · ordem 1485 na letra ε · nº geral 12724</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κεράννυμι.</p></section></article>\n<article id=\"entry-dgp-12725\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκραίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1486 na letra ε · nº geral 12725</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐξέρρανα) fazer jorrar.</p></section></article>\n<article id=\"entry-dgp-12726\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκραξα</h1><div class=\"entry-meta\"><span>DGP · ordem 1487 na letra ε · nº geral 12726</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κράζω.</p></section></article>\n<article id=\"entry-dgp-12727\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκρέμω</h1><div class=\"entry-meta\"><span>DGP · ordem 1488 na letra ε · nº geral 12727</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. impf. de κρέμαμαι.</p></section></article>\n<article id=\"entry-dgp-12728\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκρέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1489 na letra ε · nº geral 12728</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκρεύσομαι, aor. ἐξέρρευσα, aor.2 ἐξερρύην, perf. ἐξερρύηκα) 1 fluir de; escorrer de, ἐκ e gen., para, εἰς e ac. 2 cair; desaparecer 3 deixar cair; deixar escapar; perder 4 cair no esquecimento; ser esquecido.</p></section></article>\n<article id=\"entry-dgp-12729\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκρήγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1490 na letra ε · nº geral 12729</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκρήξω, aor. ἐξέρρηξα; pas. fut. ἐκρα­γήσομαι, aor.2 ἐξερράγην) 1 romper; quebrar (corda de arco) 2 arrebentar, gen. 3 fazer jorrar por fendas; fazer cair com força (chuva); deixar explodir (cólera); desabafar (lamento) 4 intr. explodir com violência 5 part. perf. ἐξερρωγώς precípite; abrupto: ἐν ὄρεσι ἐξερρωγόσι fílon em montes abruptos ♦ méd. pas. 6 romper-se 7 sair; irromper; eclodir 8 explodir.</p></section></article>\n<article id=\"entry-dgp-12730\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκριζόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1491 na letra ε · nº geral 12730</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. pas. ἐξεριζώθην) bíbl. desenraizar.</p></section></article>\n<article id=\"entry-dgp-12731\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκρίθην</h1><div class=\"entry-meta\"><span>DGP · ordem 1492 na letra ε · nº geral 12731</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κρίνω.</p></section></article>\n<article id=\"entry-dgp-12732\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκρικον</h1><div class=\"entry-meta\"><span>DGP · ordem 1493 na letra ε · nº geral 12732</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 de κρίζω.</p></section></article>\n<article id=\"entry-dgp-12733\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκρινίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1494 na letra ε · nº geral 12733</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">farejar. 〈ἐκ, ῥίς〉</p></section></article>\n<article id=\"entry-dgp-12734\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκριπίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1495 na letra ε · nº geral 12734</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">soprar o fogo; atiçar; acender.</p></section></article>\n<article id=\"entry-dgp-12735\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκριπτέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1496 na letra ε · nº geral 12735</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐκρίπτω.</p></section></article>\n<article id=\"entry-dgp-12736\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκρίπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1497 na letra ε · nº geral 12736</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 pas. ἐξερρίφην) 1 jogar fora 2 enviar para fora; desterrar de, gen. 3 emitir palavra ♦ pas. 4 ser precipitado de, gen. 5 ser banido para, εἰς e ac. 6 (ator) ser expulso; ser vaiado 7 bíbl. ir adiante em; avançar em (incursão).</p></section></article>\n<article id=\"entry-dgp-12737\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκροή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1498 na letra ε · nº geral 12737</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 escoamento 2 curso; corrente (de rio). 〈ἐκρέω〉</p></section></article>\n<article id=\"entry-dgp-12738\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκροος-ους, όου-ου (ὁ</h1><div class=\"entry-meta\"><span>DGP · ordem 1499 na letra ε · nº geral 12738</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 escoamento 2 lugar de escoamento; estuário 3 saída; meio de escapar. 〈ἐκρέω〉</p></section></article>\n<article id=\"entry-dgp-12739\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκρύβην</h1><div class=\"entry-meta\"><span>DGP · ordem 1500 na letra ε · nº geral 12739</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 pas., ἔκρυφθεν 3ª pl. aor. pas. ép., de κρύπτω.</p></section></article>\n<article id=\"entry-dgp-12740\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκσαγηνεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1501 na letra ε · nº geral 12740</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">retirar de rede.</p></section></article>\n<article id=\"entry-dgp-12741\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκσαόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1502 na letra ε · nº geral 12741</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐξεσάωσα) 1 salvar alguém, ac., de, gen. 2 salvar da morte, ac.</p></section></article>\n<article id=\"entry-dgp-12742\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκσείω</h1><div class=\"entry-meta\"><span>DGP · ordem 1503 na letra ε · nº geral 12742</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 arrancar ou tirar sacudindo (veste, pele) 2 sacudir uma pessoa, ac., para fazê-la desistir de, gen. 3 rejeitar (uma defesa) ♦ pas. 4 ser arrancado de sua base; ser lançado por terra.</p></section></article>\n<article id=\"entry-dgp-12743\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκσεύομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1504 na letra ε · nº geral 12743</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lançar-se fora de, gen. 2 ir embora; fugir de 3 correr.</p></section></article>\n<article id=\"entry-dgp-12744\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκσημαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1505 na letra ε · nº geral 12744</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indicar; explicar.</p></section></article>\n<article id=\"entry-dgp-12745\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκσκορπισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1506 na letra ε · nº geral 12745</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dispersão. 〈ἐκ, σκορπίζω〉</p></section></article>\n<article id=\"entry-dgp-12746\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκσμάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1507 na letra ε · nº geral 12746</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">enxugar.</p></section></article>\n<article id=\"entry-dgp-12747\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκσπασσαμένω</h1><div class=\"entry-meta\"><span>DGP · ordem 1508 na letra ε · nº geral 12747</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. méd. dual poét. de ἐκσπάω.</p></section></article>\n<article id=\"entry-dgp-12748\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκσπάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1509 na letra ε · nº geral 12748</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκσπάσω, aor. ἐξέσπασα) 1 arrancar 2 arrancar da base; derrubar ♦ méd. 3 arrancar de si.</p></section></article>\n<article id=\"entry-dgp-12749\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκσπονδος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1510 na letra ε · nº geral 12749</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">excluído do tratado. 〈ἐκ, σπονδή〉</p></section></article>\n<article id=\"entry-dgp-12750\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκστάδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1511 na letra ε · nº geral 12750</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de seis estádios. 〈ἕξ, στάδιον〉</p></section></article>\n<article id=\"entry-dgp-12751\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκστασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1512 na letra ε · nº geral 12751</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de deslocar; deslocamento; desvio 2 situação de ficar fora de si; perturbação; agitação; estupor; alienação; delírio 3 arrebatamento; êxtase. 〈ἐξίστημι〉</p></section></article>\n<article id=\"entry-dgp-12752\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκστατικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1513 na letra ε · nº geral 12752</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que faz mudar de lugar; que desaloja de, gen.; que incomoda 2 que faz sair de si; que perturba o espírito 3 que é levado a afastar-se de um raciocínio, gen. 4 que muda de opinião; volúvel 5 crist. arrebatado; fora de si. 〈ἐξίστημι〉</p></section></article>\n<article id=\"entry-dgp-12753\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκστατικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1514 na letra ε · nº geral 12753</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em ἐκσ. ἔχειν estar fora de si, perdido ou furioso.</p></section></article>\n<article id=\"entry-dgp-12754\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκστέλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 1515 na letra ε · nº geral 12754</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ornar; paramentar.</p></section></article>\n<article id=\"entry-dgp-12755\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκστέφω</h1><div class=\"entry-meta\"><span>DGP · ordem 1516 na letra ε · nº geral 12755</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cingir com coroas 2 dispor em forma de coroa 3 retirar a coroa, i.e., esvaziar o copo (op. a ἐπιστέφω).</p></section></article>\n<article id=\"entry-dgp-12756\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκστρατεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1517 na letra ε · nº geral 12756</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">expedição militar. 〈ἐκστρατεύω〉</p></section></article>\n<article id=\"entry-dgp-12757\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκστρατεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1518 na letra ε · nº geral 12757</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer uma expedição militar; marchar contra 2 conduzir em expedição ♦ méd. 3 sair em expedição militar 4 perf. estar em campanha ou em guerra; οἱ ἐξεστρατευμένοι ap. os veteranos.</p></section></article>\n<article id=\"entry-dgp-12758\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκστρατοπεδεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1519 na letra ε · nº geral 12758</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">acampar fora.</p></section></article>\n<article id=\"entry-dgp-12759\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκστρέφω</h1><div class=\"entry-meta\"><span>DGP · ordem 1520 na letra ε · nº geral 12759</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐξέστρεψα) 1 retirar fazendo girar: ἐκς. δένδρον βόθρου hom. arrancar uma árvore do fosso, desenraizar 2 fazer perecer; destruir 3 mudar; alterar completamente: ἔκστρεψον τοὺς σαυτοῦ τρόπους artt. muda teus hábitos ♦ méd. pas. 4 estar virado; estar invertido: πόσιν ἐξεστραμμένοις artt. com os pés voltados para trás 5 perverter-se: γενεὰ ἐξεστραμμένη sept. geração pervertida.</p></section></article>\n<article id=\"entry-dgp-12760\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκστροφή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1521 na letra ε · nº geral 12760</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">deslocação; inversão. 〈ἐκστρέφω〉</p></section></article>\n<article id=\"entry-dgp-12761\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκσυρίττω</h1><div class=\"entry-meta\"><span>DGP · ordem 1522 na letra ε · nº geral 12761</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 assobiar com força 2 expulsar com assobios.</p></section></article>\n<article id=\"entry-dgp-12762\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκσῴζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1523 na letra ε · nº geral 12762</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 salvar alguém, ac., de, gen. ou ἐκ e gen. 2 reconduzir alguém, ac., são e salvo de, παρά e gen., para, εἰς e ac. ♦ méd. 3 salvar para si 4 salvar-se; escapar de um perigo 5 refugiar-se em um lugar, ac.</p></section></article>\n<article id=\"entry-dgp-12763\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτάδην</h1><div class=\"entry-meta\"><span>DGP · ordem 1524 na letra ε · nº geral 12763</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. ao longo; ao comprido. 〈ἐκτείνω〉</p></section></article>\n<article id=\"entry-dgp-12764\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτάδιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1525 na letra ε · nº geral 12764</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">longo; largo (manto). 〈ἐκτείνω〉</p></section></article>\n<article id=\"entry-dgp-12765\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκταθείς, εῖσα, έν</h1><div class=\"entry-meta\"><span>DGP · ordem 1526 na letra ε · nº geral 12765</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. pas. de ἐκτείνω.</p></section></article>\n<article id=\"entry-dgp-12766\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκταθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1527 na letra ε · nº geral 12766</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. aor. pas. poét. de κτείνω.</p></section></article>\n<article id=\"entry-dgp-12767\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκταῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1528 na letra ε · nº geral 12767</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que acontece no sexto dia 2 sexto. 〈ἕκτος〉</p></section></article>\n<article id=\"entry-dgp-12768\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτακείη</h1><div class=\"entry-meta\"><span>DGP · ordem 1529 na letra ε · nº geral 12768</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐκτήκω.</p></section></article>\n<article id=\"entry-dgp-12769\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκταμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1530 na letra ε · nº geral 12769</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κτείνω.</p></section></article>\n<article id=\"entry-dgp-12770\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκταμε</h1><div class=\"entry-meta\"><span>DGP · ordem 1531 na letra ε · nº geral 12770</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor.2 ép. de ἐκτέμνω.</p></section></article>\n<article id=\"entry-dgp-12771\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτάμνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1532 na letra ε · nº geral 12771</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. e jôn. = ἐκτέμνω.</p></section></article>\n<article id=\"entry-dgp-12772\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτανύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1533 na letra ε · nº geral 12772</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκτανύσω, aor. ἐξετάνυσα; aor. pas. ἐξε­τανύσθην) 1 estender; esticar 2 deitar no chão (uma árvore derrubada) 3 encompridar uma via ♦ pas. 4 (guerreiro morto) estar estendido no chão.</p></section></article>\n<article id=\"entry-dgp-12773\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκταπεινόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1534 na letra ε · nº geral 12773</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rebaixar; humilhar.</p></section></article>\n<article id=\"entry-dgp-12774\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκταράσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1535 na letra ε · nº geral 12774</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω 1 perturbar; agitar; tumultuar ♦ pas. 2 Medic. ter distúrbio intestinal.</p></section></article>\n<article id=\"entry-dgp-12775\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1536 na letra ε · nº geral 12775</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 alongamento; extensão 2 extensão; desdobramento de exército 3 Gram. alongamento de vogal ou sílaba. 〈ἐκτείνω〉</p></section></article>\n<article id=\"entry-dgp-12776\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτάσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1537 na letra ε · nº geral 12776</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω 1 dispor em ordem de batalha 2 colocar em ordem; arrumar ♦ méd. 3 dispor-se em ordem de batalha.</p></section></article>\n<article id=\"entry-dgp-12777\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτάσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1538 na letra ε · nº geral 12777</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. aor. dór. de κτάομαι.</p></section></article>\n<article id=\"entry-dgp-12778\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτατο</h1><div class=\"entry-meta\"><span>DGP · ordem 1539 na letra ε · nº geral 12778</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. perf. pas. de κτείνω.</p></section></article>\n<article id=\"entry-dgp-12779\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτέαται</h1><div class=\"entry-meta\"><span>DGP · ordem 1540 na letra ε · nº geral 12779</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. pres. ind. jôn. de κτάομαι.</p></section></article>\n<article id=\"entry-dgp-12780\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτέετο</h1><div class=\"entry-meta\"><span>DGP · ordem 1541 na letra ε · nº geral 12780</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. jôn. de κτάομαι.</p></section></article>\n<article id=\"entry-dgp-12781\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτείνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1542 na letra ε · nº geral 12781</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estender 2 estender as mãos para (pegar) algo, ἐπί e ac.; estender as mãos para alguém, πρός e ac. (em ajuda, por amizade) 3 esticar as pernas; alongar o pé 4 estender no chão; estender sobre, ἐπί e ac. 5 impelir um cavalo para o chão 6 estender fortemente; esticar (cabo) 7 aplicar com esforço (o espírito, a vontade) 8 estender; desdobrar (alas, exército); desenvolver (discurso); prolongar (vida) 9 Gram. alongar uma sílaba ou uma vogal ♦ pas. 10 estender-se 11 prolongar-se 12 escoar-se; (tempo) transcorrer 13 (pessoa) estar tenso.</p></section></article>\n<article id=\"entry-dgp-12782\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτειχίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1543 na letra ε · nº geral 12782</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fortificar com muralhas 2 concluir fortificações.</p></section></article>\n<article id=\"entry-dgp-12783\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτελέεσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1544 na letra ε · nº geral 12783</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. fut. méd. ép. com sent. pas. de ἐκτελέω1.</p></section></article>\n<article id=\"entry-dgp-12784\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτελείω</h1><div class=\"entry-meta\"><span>DGP · ordem 1545 na letra ε · nº geral 12784</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐξετέλειον) = ἐκτελέω1.</p></section></article>\n<article id=\"entry-dgp-12785\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτελέσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1546 na letra ε · nº geral 12785</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. ind. e subj. aor. ép. de ἐκτελέω1.</p></section></article>\n<article id=\"entry-dgp-12786\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτελευτάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1547 na letra ε · nº geral 12786</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acabar; terminar ♦ intr. e pas. 2 acabar-se.</p></section></article>\n<article id=\"entry-dgp-12787\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτελέω1-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1548 na letra ε · nº geral 12787</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 levar a seu acabamento; acabar; terminar 2 executar; cumprir (ameaças, promessa); satisfazer (desejo) 3 percorrer até um fim; (tempo) escoar ♦ pas. 4 cumprir-se 5 (tempo) escoar-se.</p></section></article>\n<article id=\"entry-dgp-12788\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτελέω2</h1><div class=\"entry-meta\"><span>DGP · ordem 1549 na letra ε · nº geral 12788</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(3ª sing. ἐκτελέει, inf. ἐκτελέειν) fut. ép. e jôn. de ἐκτελέω1.</p></section></article>\n<article id=\"entry-dgp-12789\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτελής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1550 na letra ε · nº geral 12789</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acabado; terminado; cumprido; perfeito 2 maduro (grão).</p></section></article>\n<article id=\"entry-dgp-12790\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτεμεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 1551 na letra ε · nº geral 12790</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 at. de ἐκτέμνω.</p></section></article>\n";
